scripts.参客对话1.txt:
// 与参客的对话

	Say("参客：奇怪奇怪真奇怪，怎么钻出个姑娘来。", 0);
	Say("参客：姑娘，我这里有一些药材，要不要看看？", 0);
	
	GetPlayerLevel($PlayerLevel);
	If ($PlayerLevel << 16) @PlayerLevelL16;
	If ($PlayerLevel << 31) @PlayerLevelL31;
	Goto @PlayerLevelG30;
	Return;

@PlayerLevelL16:
	SellGoods("低级药品.ini");
	Return;
@PlayerLevelL31:
	SellGoods("中级药品.ini");
	Return;
@PlayerLevelG30:
	SellGoods("高级药品.ini");
	
	Return;

scripts.参客对话2.txt:
// 与参客的对话

	Say("参客：有什么事找我们赵大哥说吧。", 0);
	Return;

scripts.参客对话3.txt:
// 与参客的对话

	Say("参客：这么大的雪，看来我们这次上山是什么也采不到了。", 0);
	Return;

scripts.赵大帽子对话.txt:
// 与赵大帽子对话

	If ($Talkzhaoda == 0) @Talkzhaoda0;
	If ($Talkzhaoda == 1) @Talkzhaoda1;
	If ($Talkzhaoda == 2) @Talkzhaoda2;
	
@Talkzhaoda0:
	Say("赵大帽子：姑娘，你找我什么事啊？", 0);
	Say("张琳心：我需要一只千年的双头人参救人，不知……", 101);
	Say("赵大帽子：哈哈哈哈！你可知道这千年双头参是什么？", 0);
	Say("张琳心：我知道双头人参十分稀有，但是我急需用它救人！", 107);
	Say("赵大帽子：你知道吗？这种双头人参至少要五千年才能长成，真正合二为一，成为双头人参，可想而知它是多么稀有！我还是十年前看见我师傅采到一株的，但我的师傅却死在了它手里。", 0);
	Say("张琳心：无论多么困难，我都必须得到双头人参！你能帮我吗？", 103);
	Say("赵大帽子：好！俺赵大帽子就喜欢爽快人。双头参俺有，可那是俺师傅十几年前用性命换来的。你要拿走可以，但要拿条命来换！", 0);
	Say("张琳心：谁的命？", 105);
	Say("赵大帽子：杀死俺师傅的仇人——土匪许大马棒。当年他为了抢夺宝参，害死了俺师傅，此仇不共戴天！姑娘，你敢不敢答应？", 0);
	Say("张琳心：他在哪里？", 107);
	Say("赵大帽子：许大马棒平常就躲在北山的土匪窝里，经常欺压俺们这些采药打柴的。", 0);
	
	GetGoodsNum("Goods410_指南针.ini");
	If ($GoodsNum == 0) @Eventzhaoda0;
	If ($GoodsNum == 1) @Eventzhaoda1;
 @Eventzhaoda0:
	Say("张琳心：好我这就去！", 101);
	Say("赵大帽子：别急，姑娘还要取回一件事物，十年前他从俺师傅那抢走的“指南针”。有了“指南针”，不管进山多深，都不会迷路，那是俺山里人的宝贝。", 0);
	Assign($Talkzhaoda, 1);
	Return;
 @Eventzhaoda1:
 	Say("张琳心：许大马棒？我已经把他杀了！", 101);
 	Say("赵大帽子：什么？！这狗贼已经死了！", 0);
 	Say("张琳心：不错，这是我从他身上拿到的。", 101);
 	Say("赵大帽子：“指南针”！这是他十年前从师傅那抢走的……好，姑娘这双头参你拿走吧！", 0);
 	Say("张琳心：双头参！独孤哥哥有救了！", 101);
 	DelGoods("Goods410_指南针.ini");
 	AddGoods("Goods216_双头人参.ini");
 	Assign($Talkzhaoda, 2);
 	Assign($Event, 520);
 	Memo("张琳心帮助赵大帽子除掉了仇人许大马棒，得到了双头人参。");
 	Return;

 	
@Talkzhaoda1:
	GetGoodsNum("Goods410_指南针.ini");
	If ($GoodsNum == 0) @Eventzhaoda2;
	If ($GoodsNum == 1) @Eventzhaoda3;
 @Eventzhaoda2:
 	Say("赵大帽子：姑娘你命都不要，也要得到这双头人参，看来你要救的那个一定是对你非常重要的人吧？", 0);
 	Return;
 @Eventzhaoda3:
 	Say("张琳心：我已经把许大马棒杀了。", 101);
 	Say("赵大帽子：此话当真？那指南针呢？", 0);
 	Say("张琳心：在这里……", 101);
 	Say("赵大帽子：果然是师傅的遗物。好，姑娘这双头参你拿走吧！", 0);
 	Say("张琳心：太好了！独孤哥哥有救了！", 101);
 	DelGoods("Goods410_指南针.ini");
 	AddGoods("Goods216_双头人参.ini");
 	Assign($Talkzhaoda, 2);
 	Assign($Event, 520);
 	Memo("张琳心帮助赵大帽子除掉了仇人许大马棒，得到了双头人参。");
 	Return;

 	
@Talkzhaoda2:
 	Say("赵大帽子：区区一棵人参何足挂齿。姑娘替俺报了这十年的血海深仇，又为这里除了一大害，俺替大家感激你了！", 0);
 	Return;

